      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "daily": {
          "type": "array",
          "description": "从今天开始按日期升序排列的每日预报。",
          "sampleValue": [
            {
              "weekday": "今天",
              "condition": "多云",
              "temperatureRangeText": "23° / 30°",
              "rainProbabilityPercent": "35%"
            },
            {
              "weekday": "明天",
              "condition": "雷阵雨",
              "temperatureRangeText": "22° / 28°",
              "rainProbabilityPercent": "80%"
            }
          ],
          "items": {
            "type": "object",
            "description": "单日天气预报。",
            "properties": {
              "weekday": {
                "type": "string",
                "description": "星期或相对日期文本。",
                "sampleValue": "明天"
              },
              "condition": {
                "type": "string",
                "description": "白天天气现象。",
                "sampleValue": "雷阵雨"
              },
              "temperatureRangeText": {
                "type": "string",
                "description": "适合直接显示的温度范围。",
                "sampleValue": "22° / 28°"
              },
              "rainProbabilityPercent": {
                "type": "string",
                "description": "白天降雨概率百分比。",
                "sampleValue": "80%"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/alarm_fill_1.svg",
      "description": "闹钟实心图标，适合用作左侧闹钟提醒主视觉。"
    },
    {
      "src": "resources/base/media/thunderstorm.png",
      "description": "云朵、闪电和雨滴组合的彩色雷阵雨图标，适合展示明早雷阵雨天气。"
    },
    {
      "src": "resources/base/media/icon_earphone.png",
      "description": "耳机图标，适合表达戴耳机播控场景。"
    },
    {
      "src": "resources/base/media/icon_left.png",
      "description": "上一首图标，适合用于耳机音乐播控视觉按钮。"
    },
    {
      "src": "resources/base/media/play_fill.svg",
      "description": "播放实心图标，适合用于音乐播放控制按钮。"
    },
    {
      "src": "resources/base/media/icon_right.png",
      "description": "下一首图标，适合用于耳机音乐播控视觉按钮。"
    },
    {
      "src": "resources/base/media/icon_like.png",
      "description": "收藏心形图标，适合用于音乐收藏播控视觉按钮。"
    }
  ]
}

